  vis.sort((x, y) => { const a = key(x, sort[0]), b = key(y, sort[0]); return (a > b ? 1 : a < b ? -1 : 0) * sort[1]; });
  const sub = courses.slice(1).map((c) => { const g = rows.filter((r) => r.course === c && r.earned != null); const e = g.reduce((s, r) => s + r.earned, 0), p = g.reduce((s, r) => s + r.possible, 0); return [c, e, p, rows.filter((r) => r.course === c && r.earned == null).length]; });
